using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace DaServer.Generator;

/// <summary>
/// Writes the assembly's wire manifest (ADR-076) as the comment of <c>DaServer.WireManifest.g.cs</c>: with
/// <c>-p:UpdateWireManifest=true</c> the build emits the generated files and copies the comment to <c>wire.manifest</c>.
/// </summary>
[Generator(LanguageNames.CSharp)]
public sealed class WireManifestGenerator : IIncrementalGenerator
{
    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        var types = context.SyntaxProvider
            .ForAttributeWithMetadataName(Support.NinoTypeAttribute, static (node, _) => node is TypeDeclarationSyntax,
                static (ctx, _) => WireManifest.Read((INamedTypeSymbol)ctx.TargetSymbol))
            .Where(static t => t is not null)
            .Collect()
            .Select(static (all, _) => new EquatableArray<WireType>(all.Distinct().OrderBy(t => t!.Name, StringComparer.Ordinal).ToArray()!))
            .WithTrackingName("WireTypes");

        context.RegisterSourceOutput(types, static (spc, all) =>
        {
            if (all.Length == 0) return;
            // -p:UpdateWireManifest=true copies the comment's text to wire.manifest.
            spc.AddSource("DaServer.WireManifest.g.cs", "// <auto-generated/>\n/*\n" + WireManifest.Format(all.ToList()) + "*/\n");
        });
    }
}
